//! Map areas are actual live HTML collections with exact native element identity.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><map id=map name=initial>Fallback map<area id=first name=alpha><span id=nested><area id=second name=beta></span></map><area id=outside name=outside><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://map-areas.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn map_areas_native_canonical_readonly_same_object_and_tree_order(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),P=HTMLMapElement.prototype,a=Object.getOwnPropertyDescriptor(P,'areas'),list=x.areas;if(!a||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get areas'||a.get.length!==0||Object.hasOwn(x,'areas')||!(list instanceof HTMLCollection)||Object.getPrototypeOf(list)!==HTMLCollection.prototype||x.areas!==list||a.get.call(x)!==list)throw 'canonical readonly same-object areas';if(list.length!==2||list.item(0)!==document.getElementById('first')||list[1]!==document.getElementById('second')||list.item(2)!==null||list.namedItem('alpha')!==list[0]||list.namedItem('outside')!==null)throw 'native descendant area tree order and actual names';"#);
}
#[test]
fn map_areas_native_area_factory_and_moves_preexist_collection(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('map'),a=document.createElement('area');a.setAttribute('id','later');x.appendChild(a);if(document.getElementById('later')!==a||a.parentNode!==x)throw 'native area factory and connection';x.removeChild(a);if(a.parentNode!==null||document.getElementById('later')!==null)throw 'native area removal';x.appendChild(a);if(document.getElementById('later')!==a)throw 'native area reconnect';");
}
#[test]
fn map_areas_inert_namespace_filter_and_live_descendant_mutations(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),ns='http://www.w3.org/1999/xhtml',x=doc.createElementNS(ns,'map'),nested=doc.createElementNS(ns,'span'),a=doc.createElementNS(ns,'t:area'),b=doc.createElementNS(ns,'area'),upper=doc.createElementNS(ns,'AREA'),foreign=doc.createElementNS('urn:foreign','area');a.setAttribute('id','a');b.setAttribute('name','beta');x.appendChild(a);x.appendChild(nested);nested.appendChild(b);nested.appendChild(upper);nested.appendChild(foreign);var list=x.areas;if(!(list instanceof HTMLCollection)||list!==x.areas||list.length!==2||list[0]!==a||list[1]!==b||list.namedItem('beta')!==b)throw 'exact inert HTML-area descendants';x.insertBefore(b,a);if(list.length!==2||list[0]!==b||list[1]!==a)throw 'live nested area move';x.removeChild(a);if(list.length!==1||list[0]!==b||list.namedItem('a')!==null)throw 'live inert area removal';nested.appendChild(a);if(list.length!==2||list[0]!==b||list[1]!==a)throw 'descendant tree order after reconnect';");
}
#[test]
fn map_areas_native_live_moves_names_and_ignored_outside_area(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('map'),nested=document.getElementById('nested'),a=document.getElementById('first'),b=document.getElementById('second'),outside=document.getElementById('outside'),list=x.areas;x.appendChild(b);if(list!==x.areas||list.length!==2||list[0]!==a||list[1]!==b)throw 'native live area move';nested.appendChild(a);if(list[0]!==a||list[1]!==b)throw 'native live nested order';a.setAttribute('id','changed');if(list.namedItem('changed')!==a||list.namedItem('first')!==null||list.namedItem('alpha')!==a)throw 'current native area names';x.removeChild(b);if(list.length!==1||list[0]!==a||list.namedItem('beta')!==null||outside.parentNode!==document.body)throw 'native removal and outside guard';");
}

#[test]
fn map_areas_readonly_author_overrides_and_saved_interface_keep_real_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),C=HTMLMapElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'areas'),list=x.areas;x.areas=4;if(x.areas!==list||Object.hasOwn(x,'areas'))throw 'readonly inherited areas';Object.defineProperty(x,'areas',{value:'author',configurable:true});if(x.areas!=='author'||a.get.call(x)!==list)throw 'author override leaves real collection';delete x.areas;delete window.HTMLMapElement;Object.freeze(P);var b=Object.getOwnPropertyDescriptor(P,'areas');if(x.areas!==list||b.get!==a.get||b.set!==undefined||b.configurable||!b.enumerable||!(x instanceof C))throw 'saved interface and frozen readonly getter';"#);
}
#[test]
fn map_areas_accessor_rejects_forged_foreign_and_other_native_brands(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var P=HTMLMapElement.prototype,a=Object.getOwnPropertyDescriptor(P,'areas');for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','map'),new Document().createElementNS('http://www.w3.org/1999/xhtml','MAP')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'areas concrete brand';}var caught=false;try{new a.get();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'areas getter illegal construction';");
}
#[test]
fn map_areas_saved_child_origin_is_checked_before_cached_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('map'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLMapElement.prototype,'areas').get,list=get.call(x);if(list!==x.areas||list.length!==2)throw 'captured real areas getter';");p.set_location(&crate::navigation::address("https://other-map-areas.test/",&crate::navigation::Location::home()).unwrap());let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits);p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits),before);p.set_location(&crate::navigation::address("https://map-areas.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==list||list.length!==2)throw 'saved areas origin recovery';");
}
#[test]
fn map_areas_getter_refusal_is_atomic_and_cached_identity_needs_no_new_filter(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','map');"}else{"var x=document.getElementById('map');"});let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual Map handle")};let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.map_areas_get(object).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();let first=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.map_areas_get(object).unwrap();let stored=(p.state.retained,p.state.dom.collections.len());p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=1;let second=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.map_areas_get(object).unwrap();assert_eq!(format!("{first:?}"),format!("{second:?}"));assert_eq!((p.state.retained,p.state.dom.collections.len()),stored);}}
}
#[test]
fn map_areas_exact_native_id_lookup_and_inert_adoption_follow_real_nodes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),a=document.getElementById('first'),list=x.areas;a.setAttribute('id','A\ud800Z');if(list.namedItem('A\ud800Z')!==a||list.namedItem('A\ufffdZ')!==null)throw 'exact native area ID';var owner=new Document(),other=new Document(),root=owner.createElementNS('http://www.w3.org/1999/xhtml','map'),area=owner.createElementNS('http://www.w3.org/1999/xhtml','area');area.setAttribute('name','R\udfffZ');root.appendChild(area);var live=root.areas;if(other.adoptNode(root)!==root||root.ownerDocument!==other||area.ownerDocument!==other||root.areas!==live||live.length!==1||live[0]!==area||live.namedItem('R\udfffZ')!==area||live.namedItem('R\ufffdZ')!==null)throw 'same inert collection follows actual adoption';"#);
}
#[test]
fn map_areas_native_unsupported_deep_copy_refusal_keeps_collection_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('map'),list=x.areas,first=list[0];");let before=(format!("{:?}",d.nodes),p.state.dom_commits,p.state.dom.collections.len());p.begin_job();let e=p.runtime.execute("x.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Cloning this element or its native state is not implemented."),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.dom_commits,p.state.dom.collections.len()),before);p.begin_job();run(&mut d,&mut f,&mut p,"if(x.areas!==list||list.length!==2||list[0]!==first)throw 'native area copy refusal preserves live collection';x.name='recovered';if(x.name!=='recovered'||x.areas!==list)throw 'fresh metadata recovery';");
}
